template:
remote.vault "${1:default}" {
  auth.approle {
    role_id = "${2}"
    secret = "${3}"
  }
  auth.aws {
    type = "${2}"
  }
  auth.azure {
    role = "${2}"
  }
  auth.custom {
    path = "${2}"
    data = "${3}"
  }
  auth.gcp {
    role = "${2}"
    type = "${3}"
  }
  auth.kubernetes {
    role = "${2}"
  }
  auth.ldap {
    username = "${2}"
    password = "${3}"
  }
  auth.token {
    token = "${2}"
  }
  auth.userpass {
    username = "${2}"
    password = "${3}"
  }
  client_options {
  }

  // Exported fields:
  // - data (map(secret)): Data from the secret obtained from Vault.
}
